-- Kreis Offenbach (HFV) mit allen Jugend-Staffeln E–B der Saison 2026/27 (Quelle: Staffelliste des Kreises).
-- Idempotent: legt Kreis und Staffeln an bzw. aktualisiert sie über den fussball.de-Schlüssel.
do $$ declare k uuid; hfv uuid; begin
select o.id into hfv from org_units o join org_units p on p.id=o.parent_id where o.short_name='HFV' and p.name='Hessen';
select id into k from org_units where parent_id=hfv and name='Offenbach';
if k is null then insert into org_units (kind,parent_id,name) values ('kreis',hfv,'Offenbach') returning id into k; end if;
end $$;
